from __future__ import annotations

from dataclasses import dataclass


ACTIVE_STATUSES = {"Created", "Submitted", "Reserved"}
TERMINAL_STATUSES = {"Cancelled", "Shipped", "Fulfilled"}
VALID_CHANNELS = {"storefront", "oms", "customer_care"}


def _require_text(value: str, field_name: str) -> None:
    if not value.strip():
        raise ValueError(f"{field_name} required")


@dataclass(frozen=True)
class CommerceOrder:
    order_id: str
    item_id: str
    quantity: int
    status: str
    reservation_id: str
    channel: str = "storefront"
    order_minute: int = 0

    def __post_init__(self) -> None:
        _require_text(self.order_id, "order_id")
        _require_text(self.item_id, "item_id")
        if self.quantity <= 0:
            raise ValueError("quantity must be positive")
        _require_text(self.status, "status")
        _require_text(self.reservation_id, "reservation_id")
        if self.channel not in VALID_CHANNELS:
            raise ValueError("unsupported channel")
        if self.order_minute < 0:
            raise ValueError("order_minute must be non-negative")

    def is_active(self) -> bool:
        return self.status in ACTIVE_STATUSES

    def is_terminal(self) -> bool:
        return self.status in TERMINAL_STATUSES

    def cancel(self) -> "CommerceOrder":
        return CommerceOrder(
            order_id=self.order_id,
            item_id=self.item_id,
            quantity=self.quantity,
            status="Cancelled",
            reservation_id=self.reservation_id,
            channel=self.channel,
            order_minute=self.order_minute,
        )


@dataclass(frozen=True)
class InventoryBucket:
    item_id: str
    available_quantity: int
    on_order_quantity: int
    cancelled_release_quantity: int = 0
    safety_stock_quantity: int = 0
    location_id: str = "web-warehouse"

    def __post_init__(self) -> None:
        _require_text(self.item_id, "item_id")
        if self.available_quantity < 0:
            raise ValueError("available_quantity must be non-negative")
        if self.on_order_quantity < 0:
            raise ValueError("on_order_quantity must be non-negative")
        if self.cancelled_release_quantity < 0:
            raise ValueError("cancelled_release_quantity must be non-negative")
        if self.safety_stock_quantity < 0:
            raise ValueError("safety_stock_quantity must be non-negative")
        _require_text(self.location_id, "location_id")

    def release(self, quantity: int) -> "InventoryBucket":
        if quantity <= 0:
            raise ValueError("release quantity must be positive")
        if quantity > self.on_order_quantity:
            raise ValueError("release quantity exceeds on_order")
        return InventoryBucket(
            item_id=self.item_id,
            available_quantity=self.available_quantity + quantity,
            on_order_quantity=self.on_order_quantity - quantity,
            cancelled_release_quantity=self.cancelled_release_quantity + quantity,
            safety_stock_quantity=self.safety_stock_quantity,
            location_id=self.location_id,
        )

    def sellable_quantity(self) -> int:
        return max(0, self.available_quantity - self.safety_stock_quantity)


