from __future__ import annotations

from inventory_state import InventoryState, audit, replace_bucket, replace_order, release_reservation, sorted_events
from commerce_models import ACTIVE_STATUSES, CancellationEvent, CommerceOrder, InventoryBucket


def _audit(action: str, event: CancellationEvent, reason: str, reservation_id: str | None = None) -> dict[str, object]:
    return audit(action, event, reason, reservation_id)


def _cancel_order(order: CommerceOrder) -> CommerceOrder:
    return order.cancel()


def _release_inventory(buckets: list[InventoryBucket], order: CommerceOrder) -> list[InventoryBucket]:
    updated: list[InventoryBucket] = []
    for bucket in buckets:
        if bucket.item_id == order.item_id:
            updated.append(
                InventoryBucket(
                    item_id=bucket.item_id,
                    available_quantity=bucket.available_quantity,
                    on_order_quantity=bucket.on_order_quantity,
                    cancelled_release_quantity=bucket.cancelled_release_quantity,
                )
            )
        else:
            updated.append(bucket)
    return updated


def _event_is_accepted(event: CancellationEvent) -> bool:
    return event.accepted


def _released_reservation(order: CommerceOrder, event: CancellationEvent) -> dict[str, object]:
    return release_reservation(order, event)


def reconcile_cancelled_orders(
    orders: list[CommerceOrder],
    inventory: list[InventoryBucket],
    cancellation_events: list[CancellationEvent],
) -> dict[str, object]:
    orders_by_id = {order.order_id: order for order in orders}
    updated_orders = list(orders)
    updated_inventory = list(inventory)
    released_reservations: list[dict[str, object]] = []
    audit_events: list[dict[str, object]] = []
    processed_orders: set[str] = set()

    for event in sorted_events(cancellation_events):
        order = orders_by_id.get(event.order_id)
        if order is None:
            audit_events.append(_audit("ignored", event, "order_not_found"))
            continue
        if not _event_is_accepted(event):
            audit_events.append(_audit("ignored", event, "cancellation_not_accepted", order.reservation_id))
            continue
        if event.order_id in processed_orders:
            audit_events.append(_audit("ignored", event, "duplicate_cancellation", order.reservation_id))
            continue
        if order.status not in ACTIVE_STATUSES:
            audit_events.append(_audit("ignored", event, "order_not_active", order.reservation_id))
            continue

        cancelled = _cancel_order(order)
        updated_orders = replace_order(updated_orders, cancelled)
        orders_by_id[order.order_id] = cancelled
        updated_inventory = _release_inventory(updated_inventory, order)
        processed_orders.add(order.order_id)
        released_reservations.append(_released_reservation(order, event))
        audit_events.append(_audit("cancelled_order_reconciled", event, "reservation_released", order.reservation_id))

    return summarize_inventory_reconciliation(updated_orders, updated_inventory, released_reservations, audit_events)


def summarize_inventory_reconciliation(
    orders: list[CommerceOrder],
    inventory: list[InventoryBucket],
    released_reservations: list[dict[str, object]],
    audit_events: list[dict[str, object]],
) -> dict[str, object]:
    return {
        "cancelled_order_count": sum(1 for order in orders if order.status == "Cancelled"),
        "released_reservation_count": len(released_reservations),
        "audit_event_count": len(audit_events),
        "orders": orders,
        "inventory": inventory,
        "released_reservations": released_reservations,
        "audit_events": audit_events,
    }


class CommerceInventoryReconciler:
    def __init__(self, orders: list[CommerceOrder], inventory: list[InventoryBucket]) -> None:
        self.orders = list(orders)
        self.inventory = list(inventory)

    def reconcile(self, cancellation_events: list[CancellationEvent]) -> dict[str, object]:
        result = reconcile_cancelled_orders(self.orders, self.inventory, cancellation_events)
        self.orders = list(result["orders"])  # type: ignore[arg-type]
        self.inventory = list(result["inventory"])  # type: ignore[arg-type]
        return result

    def snapshot(self) -> dict[str, object]:
        return {
            "order_count": len(self.orders),
            "inventory_bucket_count": len(self.inventory),
            "cancelled_order_count": sum(1 for order in self.orders if order.status == "Cancelled"),
        }


def reconcile_with_state(
    orders: list[CommerceOrder],
    inventory: list[InventoryBucket],
    cancellation_events: list[CancellationEvent],
) -> dict[str, object]:
    state = InventoryState(orders, inventory)
    for event in sorted_events(cancellation_events):
        order = state.order_for(event)
        if order is None:
            state.accumulator.ignored(event, "order_not_found")
            continue
        if not event.accepted:
            state.accumulator.ignored(event, "cancellation_not_accepted", order.reservation_id)
            continue
        if event.order_id in state.processed_orders:
            state.accumulator.ignored(event, "duplicate_cancellation", order.reservation_id)
            continue
        if order.status not in ACTIVE_STATUSES:
            state.accumulator.ignored(event, "order_not_active", order.reservation_id)
            continue
        state.mark_cancelled(order)
        state.release_inventory(order)
        state.processed_orders.add(order.order_id)
        state.accumulator.reconciled(event, order)
    return summarize_inventory_reconciliation(
        state.orders,
        state.inventory,
        state.accumulator.released_reservations,
        state.accumulator.audit_events,
    )

