from __future__ import annotations

from commerce_models import CancellationEvent, CommerceOrder, InventoryBucket, ReconciliationAudit, ReleasedReservation


def audit(action: str, event: CancellationEvent, reason: str, reservation_id: str | None = None) -> dict[str, object]:
    return ReconciliationAudit(
        action=action,
        event_id=event.event_id,
        order_id=event.order_id,
        reservation_id=reservation_id,
        reason=reason,
    ).as_dict()


def orders_by_id(orders: list[CommerceOrder]) -> dict[str, CommerceOrder]:
    return {order.order_id: order for order in orders}


def bucket_for_item(buckets: list[InventoryBucket], item_id: str) -> InventoryBucket | None:
    for bucket in buckets:
        if bucket.item_id == item_id:
            return bucket
    return None


def replace_order(orders: list[CommerceOrder], replacement: CommerceOrder) -> list[CommerceOrder]:
    return [replacement if order.order_id == replacement.order_id else order for order in orders]


def replace_bucket(buckets: list[InventoryBucket], replacement: InventoryBucket) -> list[InventoryBucket]:
    return [replacement if bucket.item_id == replacement.item_id else bucket for bucket in buckets]


def release_reservation(order: CommerceOrder, event: CancellationEvent) -> dict[str, object]:
    return ReleasedReservation(
        reservation_id=order.reservation_id,
        order_id=order.order_id,
        item_id=order.item_id,
        quantity=order.quantity,
        event_id=event.event_id,
    ).as_dict()


def sorted_events(events: list[CancellationEvent]) -> list[CancellationEvent]:
    return sorted(events, key=lambda event: (event.event_minute, event.event_id))


class InventoryAccumulator:
    def __init__(self) -> None:
        self.released_reservations: list[dict[str, object]] = []
        self.audit_events: list[dict[str, object]] = []

    def ignored(self, event: CancellationEvent, reason: str, reservation_id: str | None = None) -> None:
        self.audit_events.append(audit("ignored", event, reason, reservation_id))

    def reconciled(self, event: CancellationEvent, order: CommerceOrder) -> None:
        self.released_reservations.append(release_reservation(order, event))
        self.audit_events.append(audit("cancelled_order_reconciled", event, "reservation_released", order.reservation_id))

    def counts(self) -> dict[str, int]:
        return {
            "released_reservation_count": len(self.released_reservations),
            "audit_event_count": len(self.audit_events),
        }


class InventoryState:
    def __init__(self, orders: list[CommerceOrder], inventory: list[InventoryBucket]) -> None:
        self.orders = list(orders)
        self.inventory = list(inventory)
        self.orders_by_id = orders_by_id(orders)
        self.processed_orders: set[str] = set()
        self.accumulator = InventoryAccumulator()

    def order_for(self, event: CancellationEvent) -> CommerceOrder | None:
        return self.orders_by_id.get(event.order_id)

    def mark_cancelled(self, order: CommerceOrder) -> CommerceOrder:
        cancelled = order.cancel()
        self.orders = replace_order(self.orders, cancelled)
        self.orders_by_id[order.order_id] = cancelled
        return cancelled

    def release_inventory(self, order: CommerceOrder) -> None:
        bucket = bucket_for_item(self.inventory, order.item_id)
        if bucket is None:
            return
        updated = bucket.release(order.quantity)
        self.inventory = replace_bucket(self.inventory, updated)

